      if (!it.nurDE || l === "DE") return basis;
      if (!l) return vermerk(basis);
      return ersatz ? ersatz(basis, l, it.nurDE) : null;
    })
    .filter(Boolean);
}

/** Inline: Satz nur mit deutschen Werten (in einem Absatz). */
export function NurDE({ land, thema, children, vermerk = true, dunkel = false }) {
  const l = landCode(land);
  if (l === "DE") return children;
  if (!l)
    return (
      <>
        {children}
        {vermerk && (
          <>
            {" "}
            <GiltFuer dunkel={dunkel} />
          </>
        )}
      </>
    );
  return <span data-land-hinweis={l}>{landHinweisText(l, thema)}.</span>;
}

/** Ganzer Absatz nur mit deutschen Werten. AT/CH: kompakte LandHinweis-Zeile. */
export function NurDEAbsatz({ land, thema, children, className, dunkel = false }) {
  const l = landCode(land);
  if (l && l !== "DE") return <LandHinweis land={l} thema={thema} zeile className={className} />;
  return (
    <p className={className}>
      {children}
      {!l && (
        <>
          {" "}
          <GiltFuer dunkel={dunkel} />
        </>
      )}
    </p>
  );
}

