  return (
    <div>
      <JsonLd daten={schema} />

      <SeitenHero
        breadcrumbs={[{ name: "Solarcarports & Parkplätze" }]}
        pill={{ marke: "Solarpflicht", text: "In acht Bundesländern gilt sie für neue Parkplätze", kurz: "Solarpflicht in acht Ländern", href: "#solarpflicht" }}
        titel={
          <>
