  "@context": "https://schema.org",
  "@type": "Service",
  "@id": `${abs(PFAD)}/#service`,
  name: "Virtuelles Kraftwerk ÖkoInvest",
  serviceType: "Virtuelles Kraftwerk: Direktvermarktung, Flexibilitätsvermarktung, Pool-Beschaffung, Monitoring",
