// Abschnittsbilder für die Länderinhalte (Gruppe 2): je Pfad und Breite ausgewählte Abschnitte als Bild.
// Aufruf: node g2-abschnitte.mjs <basis> <ausgabe> <breiten> <pfad>=<selektor1>|<selektor2> ...
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const [basis, out, breitenArg, ...auftraege] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const ctx = await browser.newContext({ reducedMotion: "reduce" });
let bannerZu = false;
for (const w of breitenArg.split(",").map(Number)) {
  const page = await ctx.newPage();
  await page.setViewportSize({ width: w, height: w < 700 ? 844 : 900 });
  for (const a of auftraege) {
    const [pfad, sel = ""] = a.split("=");
    const fehler = [];
    page.removeAllListeners("pageerror");
    page.on("pageerror", (e) => fehler.push(String(e)));
    try {
      const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 300000 });
      await page.waitForTimeout(1200);
      if (!bannerZu) await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 4000 }).then(() => (bannerZu = true)).catch(() => {});
      const breite = await page.evaluate(() => document.documentElement.scrollWidth);
      const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "start";
      const sels = sel ? sel.split("|") : [];
      let i = 0;
      for (const s of sels) {
        i++;
        const loc = page.locator(s).first();
        if (!(await loc.count())) { console.log(`   fehlt ${s}`); continue; }
        await loc.scrollIntoViewIfNeeded();
        await page.waitForTimeout(700);
        await loc.screenshot({ path: `${out}/w${w}-${name}-${i}.png` });
      }
      console.log(`${r?.status() === 200 && breite <= w && !fehler.length ? "OK  " : "!!  "} w${w} ${pfad} status=${r?.status()} breite=${breite} fehler=${fehler.length} bilder=${sels.length}`);
      fehler.slice(0, 2).forEach((f) => console.log("      ! " + f.slice(0, 160)));
    } catch (e) {
      console.log(`!!   w${w} ${pfad} LADEFEHLER ${String(e).slice(0, 120)}`);
    }
  }
  await page.close();
}
await browser.close();

